create table if not exists public.notifications (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, title text not null, message text not null default '', notification_type text not null default 'general', link_url text, read_at timestamptz, created_at timestamptz not null default now());
create index if not exists notifications_user_created_idx on public.notifications (user_id, created_at desc);

create table if not exists public.saved_events (user_id uuid not null references auth.users(id) on delete cascade, event_id bigint not null references public.events(id) on delete cascade, created_at timestamptz not null default now(), primary key (user_id, event_id));
create index if not exists saved_events_event_idx on public.saved_events (event_id);

create table if not exists public.comments (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, event_id bigint references public.events(id) on delete cascade, article_id bigint references public.articles(id) on delete cascade, parent_id bigint references public.comments(id) on delete cascade, content text not null check (length(trim(content)) between 1 and 5000), status text not null default 'pending' check (status in ('pending','approved','rejected','hidden')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint comments_one_target_chk check ((event_id is not null and article_id is null) or (event_id is null and article_id is not null)));
create index if not exists comments_event_created_idx on public.comments (event_id, created_at desc);
create index if not exists comments_article_created_idx on public.comments (article_id, created_at desc);
create index if not exists comments_user_created_idx on public.comments (user_id, created_at desc);

create table if not exists public.reports (id bigint generated by default as identity primary key, reporter_id uuid not null references auth.users(id) on delete cascade, target_type text not null check (target_type in ('comment','event','article','user')), target_id text not null, reason text not null, details text, status text not null default 'open' check (status in ('open','reviewing','resolved','dismissed')), reviewed_by uuid references auth.users(id) on delete set null, reviewed_at timestamptz, created_at timestamptz not null default now());
create index if not exists reports_status_created_idx on public.reports (status, created_at desc);
create index if not exists reports_target_idx on public.reports (target_type, target_id);

create table if not exists public.user_preferences (user_id uuid primary key references auth.users(id) on delete cascade, email_notifications boolean not null default true, event_reminders boolean not null default true, comment_notifications boolean not null default true, marketing_notifications boolean not null default false, theme text not null default 'system' check (theme in ('system','light','dark')), language text not null default 'en-GB', updated_at timestamptz not null default now());

alter table public.notifications enable row level security;
alter table public.saved_events enable row level security;
alter table public.comments enable row level security;
alter table public.reports enable row level security;
alter table public.user_preferences enable row level security;

drop policy if exists notifications_select_own on public.notifications;
create policy notifications_select_own on public.notifications for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists notifications_update_own on public.notifications;
create policy notifications_update_own on public.notifications for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
drop policy if exists notifications_insert_own on public.notifications;
create policy notifications_insert_own on public.notifications for insert to authenticated with check ((select auth.uid()) = user_id);
drop policy if exists notifications_delete_own on public.notifications;
create policy notifications_delete_own on public.notifications for delete to authenticated using ((select auth.uid()) = user_id);

drop policy if exists saved_events_select_own on public.saved_events;
create policy saved_events_select_own on public.saved_events for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists saved_events_insert_own on public.saved_events;
create policy saved_events_insert_own on public.saved_events for insert to authenticated with check ((select auth.uid()) = user_id);
drop policy if exists saved_events_delete_own on public.saved_events;
create policy saved_events_delete_own on public.saved_events for delete to authenticated using ((select auth.uid()) = user_id);

drop policy if exists comments_select_approved on public.comments;
create policy comments_select_approved on public.comments for select to anon, authenticated using (status = 'approved');
drop policy if exists comments_select_own on public.comments;
create policy comments_select_own on public.comments for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists comments_insert_own on public.comments;
create policy comments_insert_own on public.comments for insert to authenticated with check ((select auth.uid()) = user_id and status = 'pending');
drop policy if exists comments_update_own on public.comments;
create policy comments_update_own on public.comments for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id and status = 'pending');
drop policy if exists comments_delete_own on public.comments;
create policy comments_delete_own on public.comments for delete to authenticated using ((select auth.uid()) = user_id);

drop policy if exists reports_insert_own on public.reports;
create policy reports_insert_own on public.reports for insert to authenticated with check ((select auth.uid()) = reporter_id);
drop policy if exists reports_select_own on public.reports;
create policy reports_select_own on public.reports for select to authenticated using ((select auth.uid()) = reporter_id);

drop policy if exists user_preferences_select_own on public.user_preferences;
create policy user_preferences_select_own on public.user_preferences for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists user_preferences_insert_own on public.user_preferences;
create policy user_preferences_insert_own on public.user_preferences for insert to authenticated with check ((select auth.uid()) = user_id);
drop policy if exists user_preferences_update_own on public.user_preferences;
create policy user_preferences_update_own on public.user_preferences for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
drop policy if exists user_preferences_delete_own on public.user_preferences;
create policy user_preferences_delete_own on public.user_preferences for delete to authenticated using ((select auth.uid()) = user_id);

grant select, insert, update, delete on public.notifications to authenticated;
grant select, insert, delete on public.saved_events to authenticated;
grant select, insert, update, delete on public.comments to authenticated;
grant select, insert on public.reports to authenticated;
grant select, insert, update, delete on public.user_preferences to authenticated;
grant usage, select on all sequences in schema public to authenticated;
